CREATE OR REPLACE FUNCTION public.finance_schedule_prepare_sources(t uuid,m date) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE g goods_received_notes;s stock_count_sessions;q finance_entry_drafts;v jsonb;ls jsonb;debit uuid;credit uuid;amt numeric;previous numeric;change numeric;basis text;ending date:=(date_trunc('month',m)+interval '1 month -1 day')::date;n int:=0;BEGIN
IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;IF ending>(now() AT TIME ZONE 'Asia/Hong_Kong')::date THEN RAISE EXCEPTION 'Only completed months can be prepared';END IF;PERFORM finance_assert_open(t,ending);PERFORM pg_advisory_xact_lock(hashtextextended('schedule:'||t::text,0));SELECT coalesce(stock_basis,'purchases') INTO basis FROM finance_schedule_settings WHERE tenant_id=t;basis:=coalesce(basis,'purchases');
FOR g IN SELECT * FROM goods_received_notes WHERE tenant_id=t AND received_date<=ending AND status IN('received','approved','completed','confirmed') LOOP v:=finance_schedule_source(t,'grni',g.id);
IF (v->>'invoice_posted')::boolean THEN FOR q IN SELECT * FROM finance_entry_drafts WHERE tenant_id=t AND kind='grni' AND status='approved' AND source_data->>'check_id'=g.id::text LOOP
SELECT jsonb_agg(jsonb_build_object('account_id',l->>'account_id','debit',l->'credit','credit',l->'debit','venue',l->>'venue')) INTO ls FROM jsonb_array_elements(q.lines) l;PERFORM finance_schedule_enqueue(t,ending,'grni_reversal',g.grn_number||' · accrual reversal','Invoice now posted; compensating entry only','grni-reversal:'||q.id,ls,jsonb_build_object('check_kind','grni','check_id',g.id,'fingerprint',md5(v::text),'original',q.id),NULL,q.journal_entry_id);n:=n+1;END LOOP;
ELSIF NOT EXISTS(SELECT 1 FROM finance_entry_drafts WHERE tenant_id=t AND kind='grni' AND source_data->>'check_id'=g.id::text AND status IN('waiting','approved')) THEN
IF v->'lines' IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(v->'lines') l WHERE (l->>'quantity_received')::numeric<0 OR (l->>'unit_cost')::numeric<=0) THEN CONTINUE;END IF;SELECT round(sum((l->>'quantity_received')::numeric*(l->>'unit_cost')::numeric),2) INTO amt FROM jsonb_array_elements(v->'lines') l;
IF amt>0 THEN IF basis='counts' THEN debit:=finance_schedule_account(t,'1400','Inventory','asset');ELSE SELECT id INTO debit FROM chart_of_accounts WHERE tenant_id=t AND code='5110' AND account_type='cogs' AND is_active;END IF;IF debit IS NULL THEN CONTINUE;END IF;credit:=finance_schedule_account(t,'2210','Goods received not invoiced','liability');
PERFORM finance_schedule_enqueue(t,ending,'grni',g.grn_number||' · uninvoiced delivery','Confirmed delivery without posted invoice','grni:'||g.id,jsonb_build_array(jsonb_build_object('account_id',debit,'debit',amt,'credit',0,'venue',g.venue),jsonb_build_object('account_id',credit,'debit',0,'credit',amt,'venue',g.venue)),jsonb_build_object('check_kind','grni','check_id',g.id,'fingerprint',md5(v::text),'basis',basis));n:=n+1;END IF;END IF;END LOOP;
IF basis='counts' THEN FOR s IN SELECT DISTINCT ON(venue) * FROM stock_count_sessions WHERE tenant_id=t AND status='approved' AND count_type='full' AND count_date=ending ORDER BY venue,approved_at DESC LOOP
v:=finance_schedule_source(t,'stock',s.id);IF v->'lines' IS NULL OR v->'prior' IS NULL OR v->'prior'='null'::jsonb OR v->'prior_lines' IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(v->'lines') l WHERE l->>'counted_qty' IS NULL OR (l->>'unit_cost')::numeric<0) OR EXISTS(SELECT 1 FROM jsonb_array_elements(v->'prior_lines') l WHERE l->>'counted_qty' IS NULL OR (l->>'unit_cost')::numeric<0) THEN CONTINUE;END IF;
SELECT round(sum((l->>'counted_qty')::numeric*(l->>'unit_cost')::numeric),2) INTO amt FROM jsonb_array_elements(v->'lines') l;SELECT round(sum((l->>'counted_qty')::numeric*(l->>'unit_cost')::numeric),2) INTO previous FROM jsonb_array_elements(v->'prior_lines') l;change:=amt-previous;
IF change<>0 THEN SELECT id INTO credit FROM chart_of_accounts WHERE tenant_id=t AND code='5110' AND account_type='cogs' AND is_active;IF credit IS NULL THEN CONTINUE;END IF;debit:=finance_schedule_account(t,'1400','Inventory','asset');PERFORM finance_schedule_enqueue(t,ending,'stock',s.session_number||' · stock change','Approved full month-end count versus prior approved count','stock:'||s.id,jsonb_build_array(jsonb_build_object('account_id',debit,'debit',greatest(change,0),'credit',greatest(-change,0),'venue',s.venue),jsonb_build_object('account_id',credit,'debit',greatest(-change,0),'credit',greatest(change,0),'venue',s.venue)),jsonb_build_object('check_kind','stock','check_id',s.id,'fingerprint',md5(v::text),'value',amt,'previous',previous));n:=n+1;END IF;END LOOP;END IF;RETURN n;END $$;
REVOKE ALL ON FUNCTION public.finance_schedule_prepare_sources(uuid,date) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.finance_schedule_prepare_sources(uuid,date) TO authenticated;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.finance_schedule_approve(uuid,uuid,date)'::regprocedure) INTO def;
def:=replace(def,'IF q.kind IN(''tax'',''stock'',''grni'') THEN RAISE EXCEPTION ''Source revalidation not yet available for this draft kind; approval blocked'';END IF;', 'IF q.kind=''tax'' THEN RAISE EXCEPTION ''Tax source revalidation not yet available; approval blocked'';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(''schedule:''||t::text,0));
IF q.source_data ? ''check_kind'' THEN IF md5(finance_schedule_source(t,q.source_data->>''check_kind'',(q.source_data->>''check_id'')::uuid)::text) IS DISTINCT FROM q.source_data->>''fingerprint'' THEN RAISE EXCEPTION ''Source changed; cancel and prepare again'';END IF;END IF;
IF q.kind IN(''stock'',''grni'',''grni_reversal'',''asset_disposal'',''asset_reclassification'',''prepayment_funding'') AND NOT(q.source_data ? ''check_kind'') THEN RAISE EXCEPTION ''Source verification required'';END IF;
IF q.kind=''stock'' AND coalesce((SELECT stock_basis FROM finance_schedule_settings WHERE tenant_id=t),''purchases'')<>''counts'' THEN RAISE EXCEPTION ''Stock adjustments are switched off'';END IF;
IF q.kind=''grni'' AND (coalesce((SELECT stock_basis FROM finance_schedule_settings WHERE tenant_id=t),''purchases'') IS DISTINCT FROM q.source_data->>''basis'' OR EXISTS(SELECT 1 FROM goods_received_notes g JOIN journal_entries e ON e.source_id=g.invoice_id::text AND e.source_type=''invoice'' AND e.status=''posted'' AND e.tenant_id=t WHERE g.id=(q.source_data->>''check_id'')::uuid AND g.tenant_id=t)) THEN RAISE EXCEPTION ''Delivery now invoiced or stock basis changed'';END IF;
IF q.kind=''grni_reversal'' AND NOT EXISTS(SELECT 1 FROM finance_entry_drafts WHERE tenant_id=t AND id=(q.source_data->>''original'')::uuid AND status=''approved'' AND journal_entry_id=q.linked_entry_id) THEN RAISE EXCEPTION ''Original accrual unavailable'';END IF;
IF q.kind IN(''asset_opening'',''asset_acquisition'',''asset_reclassification'') AND NOT EXISTS(SELECT 1 FROM fixed_assets WHERE tenant_id=t AND id=(q.source_data->>''asset'')::uuid AND notes IN(''Opening proposal awaiting approval'',''Acquisition proposal awaiting approval'')) THEN RAISE EXCEPTION ''Asset proposal changed'';END IF;');
IF def NOT LIKE '%Source changed; cancel and prepare again%' THEN RAISE EXCEPTION 'Existing approval guard did not match';END IF;
def:=replace(def,'IF q.kind=''asset_opening'' THEN UPDATE','IF q.kind IN(''asset_acquisition'',''asset_reclassification'') THEN UPDATE fixed_assets SET amount_remaining=cost,notes=''Approved acquisition'' WHERE id=(q.source_data->>''asset'')::uuid AND tenant_id=t;END IF;
IF q.kind=''asset_disposal'' THEN UPDATE fixed_assets SET status=''disposed'',disposal_date=q.entry_date,disposal_proceeds=(q.source_data->>''proceeds'')::numeric,disposal_journal_entry_id=j,amount_remaining=0 WHERE id=(q.source_data->>''asset'')::uuid AND tenant_id=t;END IF;
IF q.kind=''prepayment_funding'' THEN UPDATE prepaid_schedules SET initial_journal_entry_id=j,amount_remaining=total_amount WHERE id=(q.source_data->>''schedule'')::uuid AND tenant_id=t AND funding_draft_id=q.id;END IF;
IF q.kind=''asset_opening'' THEN UPDATE');EXECUTE def;
SELECT pg_get_functiondef('public.finance_schedule_prepare(uuid,date)'::regprocedure) INTO def;def:=replace(def,'AND notes IS DISTINCT FROM ''Opening proposal awaiting approval''','AND notes IS DISTINCT FROM ''Opening proposal awaiting approval'' AND notes IS DISTINCT FROM ''Acquisition proposal awaiting approval''');def:=replace(def,'RETURN n;','n:=n+finance_schedule_prepare_sources(t,m);RETURN n;');EXECUTE def;END $$;
CREATE OR REPLACE FUNCTION public.finance_grni_invoice_draft() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q finance_entry_drafts;g goods_received_notes;v jsonb;ls jsonb;d date;BEGIN
IF NEW.status<>'posted' OR NEW.source_type<>'invoice' OR (TG_OP='UPDATE' AND OLD.status='posted') THEN RETURN NEW;END IF;IF NOT finance_schedule_manager(NEW.tenant_id) THEN RETURN NEW;END IF;d:=NEW.entry_date;
IF EXISTS(SELECT 1 FROM finance_closed_periods WHERE tenant_id=NEW.tenant_id AND month_start=date_trunc('month',d)::date AND reopened_at IS NULL) THEN d:=(now() AT TIME ZONE 'Asia/Hong_Kong')::date;END IF;
FOR g IN SELECT * FROM goods_received_notes WHERE tenant_id=NEW.tenant_id AND invoice_id::text=NEW.source_id LOOP v:=finance_schedule_source(NEW.tenant_id,'grni',g.id);FOR q IN SELECT * FROM finance_entry_drafts WHERE tenant_id=NEW.tenant_id AND kind='grni' AND status='approved' AND source_data->>'check_id'=g.id::text LOOP
SELECT jsonb_agg(jsonb_build_object('account_id',l->>'account_id','debit',l->'credit','credit',l->'debit','venue',l->>'venue')) INTO ls FROM jsonb_array_elements(q.lines) l;PERFORM finance_schedule_enqueue(NEW.tenant_id,d,'grni_reversal',g.grn_number||' · accrual reversal','Invoice posted; reversal awaits monthly approval','grni-reversal:'||q.id,ls,jsonb_build_object('check_kind','grni','check_id',g.id,'fingerprint',md5(v::text),'original',q.id),NULL,q.journal_entry_id);END LOOP;END LOOP;RETURN NEW;END $$;
CREATE TRIGGER finance_grni_invoice_draft AFTER INSERT OR UPDATE OF status ON public.journal_entries FOR EACH ROW EXECUTE FUNCTION public.finance_grni_invoice_draft();